WITH cleaned AS (SELECT *, LOWER(dept_name) AS dept_name_lower, CASE WHEN location IN ('Bangkok', 'Singapore') THEN 'Tier 1' ELSE 'Other' END AS location_group, COALESCE(location, 'DIRECT') AS resolved_location FROM departments WHERE location IS NOT NULL AND dept_name IN ('Finance', 'Legal')) SELECT CASE WHEN budget >= 4377000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, APPROX_PERCENTILE(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles, MAX(budget) FILTER (WHERE location = 'Chiang Mai') AS chiang_mai_max_budget, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Engineering' THEN 1 END), 0), 2) AS budget_per_engineering FROM cleaned GROUP BY CASE WHEN budget >= 4377000 THEN 'HIGH' ELSE 'LOW' END
